const getInitialTheme = () => {
  if (typeof window !== 'undefined' && window.localStorage) {
    const savedThemeMode = window.localStorage.getItem('theme');
    return savedThemeMode === 'dark' ? darkTheme : lightTheme;
  }
  return lightTheme;
};

